import{_ as n,C as s,o as h,c as e,j as i,a as l,E as o,a3 as r}from"./chunks/framework.C6R8kWFE.js";const G=JSON.parse(`{"title":"11-dars (Mentor). Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","description":"","frontmatter":{"title":"11-dars (Mentor). Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":4,"link":"/mentor/8-sinf-cs/hafta-04/"},"g":11,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","lead":"Telefoningiz yo'qolsa, undagi rasmlar ham yo'qoladimi? Agar ular «bulutda» bo'lsa — yo'q. Bugun bulut nima ekanini, fayllarni qanday yuklash va kimga qanday ruxsat bilan ulashishni o'rganamiz.","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-2-test.html","student_link":"/8-sinf-cs/hafta-04/dars-2","tabs":[{"g":10,"link":"/mentor/8-sinf-cs/hafta-04/dars-1","current":false},{"g":11,"link":"/mentor/8-sinf-cs/hafta-04/dars-2","current":true},{"g":12,"link":"/mentor/8-sinf-cs/hafta-04/dars-3","current":false}],"prev":{"g":10,"title":"Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS","link":"/mentor/8-sinf-cs/hafta-04/dars-1"},"next":{"g":12,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (2-qism): onlayn hujjatlar va vazifalarni boshqarish","link":"/mentor/8-sinf-cs/hafta-04/dars-3"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-04/dars-2.md","filePath":"mentor/8-sinf-cs/hafta-04/dars-2.md"}`),d={name:"mentor/8-sinf-cs/hafta-04/dars-2.md"},u={class:"blk"},m={id:"_1-dars-rejasi",tabindex:"-1"},g={class:"blk"},k={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},b={id:"_3-amaliy-mashg-ulotlar",tabindex:"-1"},q={class:"blk"},c={id:"_4-tezkor-savollar-checklist",tabindex:"-1"},v={class:"blk"},f={id:"_5-kuchli-o-quvchi-uchun-qo-shimcha",tabindex:"-1"},p={class:"blk"},x={id:"_6-mentor-uchun-eslatmalar",tabindex:"-1"};function z(_,a,j,D,P,T){const t=s("Icon");return h(),e("div",null,[a[18]||(a[18]=i("p",null,[i("strong",null,"Hafta:"),l(" 4 · "),i("strong",null,"Davomiyligi:"),l(" 80 daqiqa · "),i("strong",null,"Turi:"),l(" nazariya + amaliyot · "),i("strong",null,"II-bob"),l(", 5-dars (hafta ichida 2-dars)")],-1)),a[19]||(a[19]=i("blockquote",null,[i("p",null,"Manba: o'quv dasturi, 11-mavzu: «Bulutli xizmatlar tushunchasi va ularning afzalliklari. Google Drive, OneDrive, Dropbox kabi bulutli saqlash xizmatlari. Onlayn hujjatlar bilan ishlash: Google Docs, Sheets, Slides va Microsoft 365. Fayllarni yuklash, ulashish va ruxsatlarni boshqarish. Onlayn hamkorlik va vazifalarni boshqarish vositalari: Microsoft To Do, Google Tasks, Trello.» Mavzuga 3 dars ajratilgan (11–13-darslar). Ushbu 1-qismda bulut tushunchasi, saqlash xizmatlari, yuklash, ulashish va ruxsatlar; 2-qismda (12-dars) onlayn hujjatlar va vazifalarni boshqarish; 3-qismda (13-dars, 5-hafta) mustahkamlash va mini-loyiha o'tiladi.")],-1)),i("div",u,[i("h2",m,[o(t,{name:"file-text"}),a[0]||(a[0]=l(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r('<p><strong>Maqsad:</strong> o&#39;quvchilar bulutli xizmat nima ekanini va u oddiy kompyuter xotirasidan qanday farq qilishini tushunadi; Google Drive, OneDrive, Dropbox ni taqqoslaydi; faylni yuklash, papkaga joylash, ulashish va ruxsat darajasini to&#39;g&#39;ri tanlashni o&#39;rganadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>«Bulut» (cloud) ni «boshqa birovning internetga ulangan serveri» deb tushuntira oladi.</li><li>Bulutli saqlashning 4 ta afzalligini va 2 ta xavf/kamchiligini aytadi.</li><li>Google Drive, OneDrive, Dropbox ni ishlab chiqaruvchi va bepul hajm bo&#39;yicha farqlaydi.</li><li>Faylni yuklaydi, papka yaratadi, havola orqali ulashadi.</li><li>Ruxsat darajalarini (ko&#39;rish, izoh qoldirish, tahrirlash) vaziyatga qarab tanlaydi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>10-dars (IP, DNS, hosting) ni takrorlash. Savol: «Telefoningiz yo&#39;qolsa, undagi rasmlar ham yo&#39;qoladimi?»</td></tr><tr><td>10–35 daq</td><td>Yangi mavzu</td><td>Bulut tushunchasi, afzallik va xavflar, 3 xizmat, yuklash, ulashish, ruxsatlar</td></tr><tr><td>35–40 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>40–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Papka tuzilmasi, faylni yuklash, ulashish, ruxsat tanlash keyslari</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol + mini-viktorina</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Xulosa, uyga vazifa yo&#39;riqnomasi</td></tr></tbody></table><hr>',5))]),i("div",g,[i("h2",k,[o(t,{name:"file-text"}),a[3]||(a[3]=l(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=r(`<h3 id="_2-1-«bulut»-nima" tabindex="-1">2.1. «Bulut» nima? <a class="header-anchor" href="#_2-1-«bulut»-nima" aria-label="Permalink to &quot;2.1. «Bulut» nima?&quot;">​</a></h3><p><strong>Bulutli xizmat (cloud service)</strong> — fayllarni saqlash, hujjat tahrirlash yoki dastur ishlatishni o&#39;z kompyuteringizda emas, <strong>internet orqali, katta kompaniyalarning serverlarida</strong> bajarish imkonini beruvchi xizmat.</p><p>O&#39;tgan darsni eslang: sayt hosting serverida turadi. Bulut ham xuddi shunday: sizning fayllaringiz ma&#39;lumot markazidagi (data center) serverlarda saqlanadi, siz esa ularga istalgan qurilmadan internet orqali kirasiz.</p><blockquote><p>O&#39;xshatish: pulni uyda yostiq ostida saqlash — kompyuter xotirasi; bankda saqlash — bulut. Bankdagi pulni istalgan bankomatdan olasiz, bulutdagi faylni istalgan qurilmadan ochasiz.</p></blockquote><p>Muhim: «bulut» — osmondagi narsa emas. Bu boshqa birovning internetga ulangan kompyuteri (serveri).</p><h3 id="_2-2-bulutli-xizmatlarning-afzalliklari" tabindex="-1">2.2. Bulutli xizmatlarning afzalliklari <a class="header-anchor" href="#_2-2-bulutli-xizmatlarning-afzalliklari" aria-label="Permalink to &quot;2.2. Bulutli xizmatlarning afzalliklari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Afzallik</th><th>Ma&#39;nosi</th><th>Misol</th></tr></thead><tbody><tr><td><strong>Istalgan joydan kirish</strong></td><td>Internet bo&#39;lsa, fayl telefonda ham, kompyuterda ham ochiladi</td><td>Uyda boshlagan referatni maktabda davom ettirish</td></tr><tr><td><strong>Zaxira nusxa (backup)</strong></td><td>Qurilma buzilsa yoki yo&#39;qolsa ham fayl saqlanib qoladi</td><td>Telefon yo&#39;qoldi, rasmlar Google Photos da qoldi</td></tr><tr><td><strong>Ulashish oson</strong></td><td>Katta faylni xatga qo&#39;shmasdan, havola bilan yuborish</td><td>500 MB videoni sinfdoshga havola bilan berish</td></tr><tr><td><strong>Hamkorlik</strong></td><td>Bir hujjat ustida bir vaqtda bir necha kishi ishlaydi</td><td>Guruh loyihasi taqdimoti</td></tr><tr><td><strong>Sinxronizatsiya</strong></td><td>Bir qurilmadagi o&#39;zgarish boshqalarida ham paydo bo&#39;ladi</td><td>Kompyuterda o&#39;zgartirilgan fayl telefonda yangilangan holda ochiladi</td></tr></tbody></table><h3 id="_2-3-kamchiliklar-va-xavflar" tabindex="-1">2.3. Kamchiliklar va xavflar <a class="header-anchor" href="#_2-3-kamchiliklar-va-xavflar" aria-label="Permalink to &quot;2.3. Kamchiliklar va xavflar&quot;">​</a></h3><ul><li><strong>Internetga bog&#39;liqlik:</strong> internet bo&#39;lmasa, oflayn rejim yoqilmagan fayllarni ocha olmaysiz.</li><li><strong>Joy cheklangan:</strong> bepul hajm tugasa, yangi fayl yuklanmaydi.</li><li><strong>Maxfiylik:</strong> noto&#39;g&#39;ri ulashilgan havola orqali begonalar shaxsiy faylni ko&#39;rishi mumkin.</li><li><strong>Akkaunt xavfsizligi:</strong> parol o&#39;g&#39;irlansa, barcha fayllar xavf ostida (14-mavzuda kuchli parol va 2FA ni o&#39;rganamiz).</li></ul><h3 id="_2-4-mashhur-bulutli-saqlash-xizmatlari" tabindex="-1">2.4. Mashhur bulutli saqlash xizmatlari <a class="header-anchor" href="#_2-4-mashhur-bulutli-saqlash-xizmatlari" aria-label="Permalink to &quot;2.4. Mashhur bulutli saqlash xizmatlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Xizmat</th><th>Kompaniya</th><th>Bepul hajm</th><th>Qachon qulay</th></tr></thead><tbody><tr><td><strong>Google Drive</strong></td><td>Google</td><td>15 GB (Gmail va Google Photos bilan umumiy)</td><td>Google akkaunti bor, Google Docs/Sheets/Slides ishlatiladi</td></tr><tr><td><strong>OneDrive</strong></td><td>Microsoft</td><td>5 GB</td><td>Windows va Microsoft 365 (Word, Excel, PowerPoint) bilan ishlanadi</td></tr><tr><td><strong>Dropbox</strong></td><td>Dropbox</td><td>2 GB</td><td>Fayllarni turli qurilmalar o&#39;rtasida tez sinxronlash</td></tr></tbody></table><p>Hajm raqamlari vaqt o&#39;tishi bilan o&#39;zgarishi mumkin; har bir xizmatda pullik tariflar ham bor. Uchala xizmatda ham veb-versiya (brauzer orqali), kompyuter dasturi va telefon ilovasi mavjud.</p><blockquote><p>Hajmni his qilish uchun: 15 GB ≈ 5000 ta telefon rasmi (har biri ~3 MB) (taxminiy hisob).</p></blockquote><h3 id="_2-5-akkaunt-va-kirish" tabindex="-1">2.5. Akkaunt va kirish <a class="header-anchor" href="#_2-5-akkaunt-va-kirish" aria-label="Permalink to &quot;2.5. Akkaunt va kirish&quot;">​</a></h3><p>Bulutli xizmatdan foydalanish uchun <strong>akkaunt</strong> kerak: Google Drive uchun Google akkaunti (Gmail), OneDrive uchun Microsoft akkaunti (Outlook/Hotmail). Kirish: <code>drive.google.com</code>, <code>onedrive.live.com</code>, <code>dropbox.com</code> — doim <code>https://</code> va to&#39;g&#39;ri domenni tekshiring (10-dars).</p><p>Maktab kompyuterida ishlagandan so&#39;ng <strong>akkauntdan chiqing</strong> (Sign out / Chiqish), aks holda keyingi odam fayllaringizni ko&#39;radi.</p><h3 id="_2-6-fayllarni-yuklash-va-tartiblash" tabindex="-1">2.6. Fayllarni yuklash va tartiblash <a class="header-anchor" href="#_2-6-fayllarni-yuklash-va-tartiblash" aria-label="Permalink to &quot;2.6. Fayllarni yuklash va tartiblash&quot;">​</a></h3><p>Google Drive misolida (OneDrive va Dropbox da tugmalar nomi o&#39;xshash):</p><ol><li><code>drive.google.com</code> ga kiring.</li><li><strong>Yangi (New)</strong> tugmasini bosing.</li><li><strong>Papka yaratish (New folder)</strong> — masalan, <code>8-sinf CS</code>.</li><li>Papkani oching, <strong>Yangi → Fayl yuklash (File upload)</strong> yoki <strong>Papka yuklash (Folder upload)</strong> ni tanlang.</li><li>Faylni sichqoncha bilan brauzer oynasiga <strong>sudrab tashlash (drag and drop)</strong> ham mumkin.</li></ol><p>Tartib qoidalari:</p><ul><li>Fayl nomi ma&#39;noli bo&#39;lsin: <code>Referat_Internet_Karimov.docx</code>, <code>IMG_2034.jpg</code> emas.</li><li>Papkalar mavzu yoki fan bo&#39;yicha: <code>Matematika</code>, <code>CS/4-hafta</code>.</li><li>Keraksiz fayllarni o&#39;chiring: <strong>Savat (Trash/Bin)</strong> ga tushadi va odatda 30 kundan keyin butunlay o&#39;chadi.</li></ul><h3 id="_2-7-fayllarni-ulashish" tabindex="-1">2.7. Fayllarni ulashish <a class="header-anchor" href="#_2-7-fayllarni-ulashish" aria-label="Permalink to &quot;2.7. Fayllarni ulashish&quot;">​</a></h3><p>Faylni ulashishning ikki yo&#39;li bor:</p><ol><li><strong>Aniq odamga (email bo&#39;yicha):</strong> fayl ustida o&#39;ng tugma → <strong>Ulashish (Share)</strong> → odamning email manzilini yozing → ruxsat darajasini tanlang → <strong>Yuborish</strong>.</li><li><strong>Havola orqali:</strong> <strong>Ulashish → Havolani nusxalash (Copy link)</strong>. Umumiy kirish (General access) sozlamasi: <ul><li><strong>Cheklangan (Restricted)</strong> — faqat qo&#39;shilgan odamlar ochadi.</li><li><strong>Havolasi bor har kim (Anyone with the link)</strong> — havolani olgan istalgan odam ochadi.</li></ul></li></ol><blockquote><p>Havola — kalitning nusxasi. «Havolasi bor har kim» rejimida havolani qayerga tashlasangiz, u yerdagi hamma faylni ochadi.</p></blockquote><h3 id="_2-8-ruxsatlarni-boshqarish" tabindex="-1">2.8. Ruxsatlarni boshqarish <a class="header-anchor" href="#_2-8-ruxsatlarni-boshqarish" aria-label="Permalink to &quot;2.8. Ruxsatlarni boshqarish&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Daraja (Google Drive)</th><th>Nima qila oladi</th><th>Qachon tanlanadi</th></tr></thead><tbody><tr><td><strong>Ko&#39;ruvchi (Viewer)</strong></td><td>faqat ko&#39;radi va (ruxsat berilsa) yuklab oladi</td><td>dars materiali, e&#39;lon, tayyor taqdimot</td></tr><tr><td><strong>Izohlovchi (Commenter)</strong></td><td>ko&#39;radi va izoh (comment) qoldiradi, matnni o&#39;zgartirmaydi</td><td>o&#39;qituvchi yoki do&#39;st xatoni ko&#39;rsatib berishi kerak</td></tr><tr><td><strong>Muharrir (Editor)</strong></td><td>o&#39;zgartiradi, o&#39;chiradi, boshqalarga ulashadi</td><td>guruh loyihasidagi jamoadoshlar</td></tr></tbody></table><p>OneDrive da: <strong>Ko&#39;rish mumkin (Can view)</strong> va <strong>Tahrirlash mumkin (Can edit)</strong>. Dropbox da: <strong>Can view</strong> va <strong>Can edit</strong>.</p><p><strong>Eng kam ruxsat qoidasi:</strong> odamga ishi uchun yetadigan eng kichik ruxsatni bering. Ulashishni istalgan vaqtda bekor qilish mumkin: <strong>Ulashish → odam yonidagi ro&#39;yxat → Kirishni olib tashlash (Remove access)</strong>.</p><h3 id="_2-9-xavfsiz-ulashish-qoidalari" tabindex="-1">2.9. Xavfsiz ulashish qoidalari <a class="header-anchor" href="#_2-9-xavfsiz-ulashish-qoidalari" aria-label="Permalink to &quot;2.9. Xavfsiz ulashish qoidalari&quot;">​</a></h3><ul><li>Pasport nusxasi, parollar, shaxsiy rasmlar — <strong>«Havolasi bor har kim»</strong> rejimida hech qachon ulashilmaydi.</li><li>Havolani ijtimoiy tarmoq yoki ochiq guruhlarga tashlashdan oldin o&#39;ylang.</li><li>Loyiha tugagach, keraksiz ruxsatlarni olib tashlang.</li><li>Begonadan kelgan «faylni ochish uchun parolingizni kiriting» havolalariga ishonmang: domenni tekshiring.</li></ul><h3 id="_2-10-butun-rasm" tabindex="-1">2.10. Butun rasm <a class="header-anchor" href="#_2-10-butun-rasm" aria-label="Permalink to &quot;2.10. Butun rasm&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Qurilma (telefon/kompyuter) -&gt; internet (HTTPS) -&gt; bulut serveri (Drive, OneDrive, Dropbox)</span></span>
<span class="line"><span>            yuklash -&gt;                       &lt;- yuklab olish</span></span>
<span class="line"><span>            ulashish: havola + ruxsat (ko&#39;rish / izoh / tahrir)</span></span></code></pre></div><hr>`,34))]),i("div",y,[i("h2",b,[o(t,{name:"file-text"}),a[6]||(a[6]=l(" 3. Amaliy mashg'ulotlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-mashg-ulotlar","aria-label":`Permalink to "<Icon name="file-text" /> 3. Amaliy mashg'ulotlar"`},"​",-1))]),a[8]||(a[8]=r('<blockquote><p>Maktab kompyuterlarida o&#39;quvchilarning shaxsiy akkaunti bo&#39;lmasa yoki 13 yoshga to&#39;lmagan bo&#39;lsa: mentor o&#39;z ekranida ko&#39;rsatadi yoki maktab (o&#39;quv) akkauntidan foydalaniladi; o&#39;quvchilar 1, 3, 4, 5-mashqlarni daftarda bajaradi.</p></blockquote><h3 id="_1-mashq-oson-bulutmi-yoki-qurilmami" tabindex="-1">1-mashq (oson). Bulutmi yoki qurilmami? <a class="header-anchor" href="#_1-mashq-oson-bulutmi-yoki-qurilmami" aria-label="Permalink to &quot;1-mashq (oson). Bulutmi yoki qurilmami?&quot;">​</a></h3><p><strong>Vazifa:</strong> Har bir holat bo&#39;yicha fayl qayerda saqlanayotganini aniqlang (qurilma xotirasi yoki bulut): (a) USB-fleshkadagi referat; (b) Google Drive dagi taqdimot; (c) telefon galereyasidagi, hech qayerga yuklanmagan rasm; (d) Google Photos ga avtomatik yuklangan rasm; (e) kompyuterning «Ish stoli» dagi Word fayl.</p><p><strong>Yechim:</strong> bulut — (b), (d); qurilma — (a), (c), (e).</p><h3 id="_2-mashq-oson-papka-tuzilmasini-yaratish" tabindex="-1">2-mashq (oson). Papka tuzilmasini yaratish <a class="header-anchor" href="#_2-mashq-oson-papka-tuzilmasini-yaratish" aria-label="Permalink to &quot;2-mashq (oson). Papka tuzilmasini yaratish&quot;">​</a></h3><p><strong>Vazifa:</strong> Google Drive (yoki OneDrive) da <code>8-sinf CS</code> papkasini, uning ichida <code>4-hafta</code> papkasini yarating. Kompyuterdagi bitta faylni (yoki mentor bergan namunani) shu papkaga yuklang va ma&#39;noli nom bering.</p><p><strong>Yechim:</strong> Yangi → Papka → <code>8-sinf CS</code>; ichida Yangi → Papka → <code>4-hafta</code>; Yangi → Fayl yuklash. Fayl nomi masalan <code>Internet_konspekt_Aliyev.docx</code>. Tekshirish: papka yo&#39;li ko&#39;rinadi <code>Mening diskim &gt; 8-sinf CS &gt; 4-hafta</code>.</p><h3 id="_3-mashq-o-rta-qaysi-ruxsat" tabindex="-1">3-mashq (o&#39;rta). Qaysi ruxsat? <a class="header-anchor" href="#_3-mashq-o-rta-qaysi-ruxsat" aria-label="Permalink to &quot;3-mashq (o&#39;rta). Qaysi ruxsat?&quot;">​</a></h3><p><strong>Vazifa:</strong> Har bir vaziyat uchun ruxsat darajasini tanlang (Ko&#39;ruvchi, Izohlovchi, Muharrir) va sababini yozing:</p><ol><li>Sinfga dars jadvalini yubordingiz.</li><li>Guruh loyihasi taqdimotini 3 jamoadosh bilan birga tayyorlaysiz.</li><li>Ustozingiz insholaringizni o&#39;qib, xatolarga izoh yozishi kerak.</li><li>Buvingizga oilaviy rasmlar albomini yubordingiz.</li></ol><p><strong>Yechim:</strong> 1 — Ko&#39;ruvchi (hamma o&#39;qisin, o&#39;zgartirmasin); 2 — Muharrir (birga tahrirlash); 3 — Izohlovchi (izoh yozadi, matn o&#39;zgarmaydi); 4 — Ko&#39;ruvchi. Asosiy fikr: eng kam yetarli ruxsat.</p><h3 id="_4-mashq-o-rta-xavfli-ulashishni-toping" tabindex="-1">4-mashq (o&#39;rta). Xavfli ulashishni toping <a class="header-anchor" href="#_4-mashq-o-rta-xavfli-ulashishni-toping" aria-label="Permalink to &quot;4-mashq (o&#39;rta). Xavfli ulashishni toping&quot;">​</a></h3><p><strong>Vazifa:</strong> Qaysi holatlarda xatolik bor va qanday tuzatish kerak? (a) Pasport nusxasi «Havolasi bor har kim — Muharrir» qilib Telegram guruhiga tashlangan. (b) Sinf jadvali «Havolasi bor har kim — Ko&#39;ruvchi» qilib sinf guruhiga yuborilgan. (c) Loyiha tugagan, lekin 2 oy oldingi begona ishtirokchi hali ham Muharrir.</p><p><strong>Yechim:</strong> (a) xato: shaxsiy hujjat ochiq havola bilan va tahrir ruxsati bilan berilgan → kirishni «Cheklangan» ga o&#39;tkazish, havolani o&#39;chirish; (b) to&#39;g&#39;ri; (c) xato → ishtirokchini «Kirishni olib tashlash».</p><h3 id="_5-mashq-qiyin-xizmatlarni-taqqoslash" tabindex="-1">5-mashq (qiyin). Xizmatlarni taqqoslash <a class="header-anchor" href="#_5-mashq-qiyin-xizmatlarni-taqqoslash" aria-label="Permalink to &quot;5-mashq (qiyin). Xizmatlarni taqqoslash&quot;">​</a></h3><p><strong>Vazifa:</strong> Google Drive, OneDrive va Dropbox ni 4 mezon bo&#39;yicha jadvalda taqqoslang: kompaniya, bepul hajm, qaysi ofis dasturlari bilan bog&#39;liq, sizga qaysi biri qulay va nima uchun.</p><p><strong>Yechim (namuna):</strong> Google Drive — Google, 15 GB, Docs/Sheets/Slides; OneDrive — Microsoft, 5 GB, Word/Excel/PowerPoint (Microsoft 365); Dropbox — Dropbox, 2 GB, alohida ofis paketi yo&#39;q, sinxronlash uchun qulay. Oxirgi ustun — asoslangan shaxsiy tanlov (har qanday mantiqli javob qabul).</p><hr>',18))]),i("div",q,[i("h2",c,[o(t,{name:"file-text"}),a[9]||(a[9]=l(" 4. Tezkor savollar (Checklist) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-savollar-checklist","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor savollar (Checklist)"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Bulutli xizmat nima? <ul><li><strong>Javob:</strong> Fayl va dasturlarni internet orqali kompaniya serverlarida saqlash va ishlatish xizmati.</li></ul></li><li>Bulutning 3 ta afzalligini ayting. <ul><li><strong>Javob:</strong> Istalgan joydan kirish, zaxira nusxa, oson ulashish (yana: hamkorlik, sinxronizatsiya).</li></ul></li><li>Google Drive da bepul qancha joy beriladi? <ul><li><strong>Javob:</strong> 15 GB (Gmail va Photos bilan umumiy).</li></ul></li><li>«Izohlovchi» ruxsati «Muharrir» dan nimasi bilan farq qiladi? <ul><li><strong>Javob:</strong> Izohlovchi faqat izoh qoldiradi, matnni o&#39;zgartira olmaydi; Muharrir o&#39;zgartiradi.</li></ul></li><li>«Havolasi bor har kim» rejimining xavfi nimada? <ul><li><strong>Javob:</strong> Havolani olgan har qanday odam, hatto begona ham, faylni ochadi.</li></ul></li></ol>",1))]),i("div",v,[i("h2",f,[o(t,{name:"file-text"}),a[12]||(a[12]=l(" 5. Kuchli o'quvchi uchun qo'shimcha ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-kuchli-o-quvchi-uchun-qo-shimcha","aria-label":`Permalink to "<Icon name="file-text" /> 5. Kuchli o'quvchi uchun qo'shimcha"`},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,"Oflayn rejim: Google Drive da fayllarni internetsiz ochish uchun «Oflayn rejimda mavjud» sozlamasini toping."),i("li",null,"Saqlash hajmi qayerda ko'rinadi? (Drive: chap pastda «Xotira»; OneDrive: Sozlamalar → Xotira.) Akkauntingizda qancha joy band ekanini hisoblang.")],-1))]),i("div",p,[i("h2",x,[o(t,{name:"file-text"}),a[15]||(a[15]=l(" 6. Mentor uchun eslatmalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-eslatmalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun eslatmalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"Google va Microsoft akkauntlari uchun yosh chegarasi bor (ko'p mamlakatlarda 13 yosh): shaxsiy akkaunti bo'lmagan o'quvchilarni majburlamang, ota-ona yoki maktab akkaunti bilan ishlash mumkin."),i("li",null,"Mentor oldindan namuna papka va namuna fayl tayyorlab qo'ysin; internet sekin bo'lsa, kichik (≤1 MB) fayl ishlating."),i("li",null,"Dars oxirida barcha o'quvchilar maktab kompyuterlarida akkauntdan chiqqanini tekshiring."),i("li",null,"Bepul hajm raqamlari o'zgarishi mumkin: darsdan oldin xizmat saytida tekshirib qo'ying.")],-1))])])}const S=n(d,[["render",z]]);export{G as __pageData,S as default};
